      "doc.toc.mcp": "MCP Servers",
      "doc.toc.search": "Búsqueda en historial",
      "doc.toc.explorer": "Explorador",
      "doc.toc.skills": "Habilidades",
      "doc.toc.hf": "Conjuntos de datos HF",
      "doc.toc.llm": "LLM &amp; Brain",
